import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Random;

/**
 * Answers course questions using keyword replies and random general replies.
 * Records keyword counts, distinct topics, and ratings.
 * Matching is by substring; questions with several known keywords have
 * no promised priority. This simple example uses non-null English text.
 * @author Pranjal Patra
 * @version 2.0
 */
public class HelpBot
{
    /** The inclusive rating range. */
    public static final int MIN_RATING = 1;
    public static final int MAX_RATING = 5;
    private static final String NO_QUESTION = "Please type a question.";
    private static final String UNKNOWN_KEYWORD = "I do not have an answer for that yet.";
    private static int botsCreated = 0;

    private HashMap<String, String> replyMap;
    private HashMap<String, Integer> keywordCounts;
    private HashSet<String> topicsAsked;
    private ArrayList<String> generalReplies;
    private ArrayList<Integer> ratings;
    private Random randomGenerator;

    /**
     * Create a help bot with fixed replies, no recorded topics, and no ratings.
     */
    public HelpBot()
    {
        generalReplies = new ArrayList<>();
        ratings = new ArrayList<>();
        randomGenerator = new Random();
        fillGeneralReplies();
        replyMap = new HashMap<>();
        keywordCounts = new HashMap<>();
        topicsAsked = new HashSet<>();
        fillReplyMap();
        botsCreated++;
    }

    /**
     * Answer one question by matching a known keyword, or use a general reply.
     * @param question The text typed by the user; must not be null.
     * @return A keyword reply, a general reply, or the empty-question prompt.
     */
    public String replyTo(String question)
    {
        String cleaned = clean(question);
        if(cleaned.isEmpty()) {
            return NO_QUESTION;
        }
        for(String keyword : replyMap.keySet()) {
            if(cleaned.contains(keyword)) {
                recordKeyword(keyword);
                return replyMap.get(keyword);
            }
        }
        return pickGeneralReply();
    }

    /**
     * Remove the spaces around a question and put it in lower case.
     * Each String method returns a result, so the result must be
     * used or stored.
     * @param question The text typed by the user; must not be null.
     * @return The cleaned text.
     */
    public String clean(String question)
    {
        return question.trim().toLowerCase();
    }

    /**
     * Choose one general reply at random. The call nextInt(bound)
     * returns a value from 0 up to bound - 1, which is exactly the set
     * of valid indices for a list of that size.
     * @return One of the general replies.
     */
    public String pickGeneralReply()
    {
        int index = randomGenerator.nextInt(generalReplies.size());
        return generalReplies.get(index);
    }

    /**
     * Record how useful a reply was. Ratings outside 1 to 5 are ignored.
     * The int value is boxed into an Integer as it enters the list.
     * @param rating A rating from 1 to 5.
     */
    public void addRating(int rating)
    {
        if(rating >= MIN_RATING && rating <= MAX_RATING) {
            ratings.add(rating);
        }
    }

    /**
     * @return The number of ratings recorded so far.
     */
    public int numberOfRatings()
    {
        return ratings.size();
    }

    /**
     * Work out the average of the recorded ratings. Each Integer in the
     * list is unboxed into the int loop variable.
     * @return The whole-number average, or 0 when no rating exists.
     */
    public int averageRating()
    {
        if(ratings.isEmpty()) {
            return 0;
        }
        int total = 0;
        for(int rating : ratings) {
            total = total + rating;
        }
        return total / ratings.size();
    }

    /**
     * @return The number of general replies available.
     */
    public int numberOfGeneralReplies()
    {
        return generalReplies.size();
    }

    /**
     * Report whether a given reply is one this bot can give.
     * @param reply The text to look for.
     * @return true when the text is one of the general replies.
     */
    public boolean hasGeneralReply(String reply)
    {
        return generalReplies.contains(reply);
    }

    /**
     * Build the list of general replies. This method is private because
     * it is a step in building a HelpBot, not an operation that other
     * classes should call.
     */
    private void fillGeneralReplies()
    {
        generalReplies.add("Can you describe that in more detail?");
        generalReplies.add("Have you checked the course web page?");
        generalReplies.add("That question comes up often. Let us look at it together.");
        generalReplies.add("Please post that on the discussion board so others can see the answer.");
    }

    /**
     * Look up an exact keyword without recording a question.
     * @param keyword A non-null keyword.
     * @return Its reply, or the unknown-keyword message if absent.
     */
    public String replyFor(String keyword)
    {
        return replyMap.getOrDefault(keyword, UNKNOWN_KEYWORD);
    }

    /**
     * @param keyword A non-null keyword.
     * @return true if the keyword has a stored reply.
     */
    public boolean knows(String keyword)
    {
        return replyMap.containsKey(keyword);
    }

    /**
     * Add or replace the reply for one exact keyword.
     * @param keyword A non-null lowercase keyword.
     * @param reply A non-null reply.
     */
    public void learn(String keyword, String reply)
    {
        replyMap.put(keyword, reply);
    }

    /** @return The number of keyword/reply entries. */
    public int numberOfKeywords()
    {
        return replyMap.size();
    }

    /**
     * @param keyword A non-null keyword.
     * @return Its recorded count, or 0 if it has never matched.
     */
    public int timesAsked(String keyword)
    {
        return keywordCounts.getOrDefault(keyword, 0);
    }

    /** @return The number of different recorded topics. */
    public int numberOfTopicsAsked()
    {
        return topicsAsked.size();
    }

    /**
     * @param keyword A non-null keyword.
     * @return true if the keyword has been recorded.
     */
    public boolean hasBeenAsked(String keyword)
    {
        return topicsAsked.contains(keyword);
    }

    /** @return The number of bots constructed in this JVM. */
    public static int numberOfBots()
    {
        return botsCreated;
    }

    /**
     * Record a recognised keyword in the count map and topic set.
     * @param keyword The keyword that matched; must not be null.
     */
    private void recordKeyword(String keyword)
    {
        int count = keywordCounts.getOrDefault(keyword, 0);
        keywordCounts.put(keyword, count + 1);
        topicsAsked.add(keyword);
    }

    /** Fill the four fixed keyword replies during construction. */
    private void fillReplyMap()
    {
        replyMap.put("submit",
            "Upload your .java files to the assignment page before the deadline.");
        replyMap.put("compile",
            "Read the first error message and check the line just above it.");
        replyMap.put("late", "Late work loses 10 percent per day.");
        replyMap.put("test", "Term Test 2 covers Chapters 1 to 9 and 12 to 13, mostly 6 to 9 and 12 to 13.");
    }
}
